        print(json.dumps({"error": "no_state"}))
        sys.exit(1)

    lane = state["lanes"].get(
        args.lane,
        {
            "stage": "queued",
            "stages": {},
            "files_touched": [],
            "depends_on": [],
            "blocked_on_dependency": [],
